mapper.select:
SELECT * FROM posts


        post_type = #{postType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


        AND status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}


        AND user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}


ORDER BY is_top DESC, created_at DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE posts
title = #{title}, content = #{content}, images = #{images, typeHandler=com.flittly.bankendspringboot.config.JsonListTypeHandler}, status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}, is_top = #{isTop}, updated_at = NOW()
WHERE id = #{id, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
